class Solution {
public:
    long long sumRemoteness(vector<vector<int>>& grid) {
        int n = grid.size();
        long long total_sum = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != -1) total_sum += grid[r][c];
            }
        }
        vector<vector<bool>> visited(n, vector<bool>(n, false));
        long long ans = 0;
        int dr[] = {1, -1, 0, 0};
        int dc[] = {0, 0, 1, -1};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != -1 && !visited[r][c]) {
                    vector<pair<int, int>> q = {{r, c}};
                    visited[r][c] = true;
                    long long comp_sum = 0, comp_cnt = 0;
                    while (!q.empty()) {
                        auto [cr, cc] = q.back();
                        q.pop_back();
                        comp_sum += grid[cr][cc];
                        comp_cnt++;
                        for (int k = 0; k < 4; k++) {
                            int nr = cr + dr[k], nc = cc + dc[k];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != -1 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                q.push_back({nr, nc});
                            }
                        }
                    }
                    ans += comp_cnt * (total_sum - comp_sum);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public long sumRemoteness(int[][] grid) {
        int n = grid.length;
        long totalSum = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != -1) totalSum += grid[r][c];
            }
        }
        boolean[][] visited = new boolean[n][n];
        long ans = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != -1 && !visited[r][c]) {
                    Queue<int[]> q = new LinkedList<>();
                    q.add(new int[]{r, c});
                    visited[r][c] = true;
                    long compSum = 0, compCnt = 0;
                    while (!q.isEmpty()) {
                        int[] curr = q.poll();
                        compSum += grid[curr[0]][curr[1]];
                        compCnt++;
                        for (int k = 0; k < 4; k++) {
                            int nr = curr[0] + dr[k], nc = curr[1] + dc[k];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != -1 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                q.add(new int[]{nr, nc});
                            }
                        }
                    }
                    ans += compCnt * (totalSum - compSum);
                }
            }
        }
        return ans;
    }
}

