var sumRemoteness = function(grid) {
    const n = grid.length;
    let totalSum = 0n;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== -1) totalSum += BigInt(grid[r][c]);
        }
    }
    const visited = Array.from({ length: n }, () => new Uint8Array(n));
    let ans = 0n;
    const dr = [1, -1, 0, 0];
    const dc = [0, 0, 1, -1];
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== -1 && !visited[r][c]) {
                const q = [[r, c]];
                visited[r][c] = 1;
                let compSum = 0n, compCnt = 0n;
                while (q.length > 0) {
                    const [cr, cc] = q.pop();
                    compSum += BigInt(grid[cr][cc]);
                    compCnt++;
                    for (let k = 0; k < 4; k++) {
                        const nr = cr + dr[k], nc = cc + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] !== -1 && !visited[nr][nc]) {
                            visited[nr][nc] = 1;
                            q.push([nr, nc]);
                        }
                    }
                }
                ans += compCnt * (totalSum - compSum);
            }
        }
    }
    return Number(ans);
};
